using Microsoft.ML.Data;

namespace ChurnPredictor.Models;

public class ChurnInput
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    public string Churned { get; set; } = string.Empty;
}

using Microsoft.ML.Data;

namespace ChurnPredictor.Models;

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }

    public float Score { get; set; }
}

namespace ChurnPredictor.Models;

public class PredictRequest
{
    public float Age { get; set; }
    public float Income { get; set; }
    public string Region { get; set; } = string.Empty;
    public float PurchaseHistory { get; set; }
}

using Microsoft.ML;
using Microsoft.ML.Data;
using ChurnPredictor.Models;

namespace ChurnPredictor.Services;

public class ModelTrainerService
{
    private readonly ILogger<ModelTrainerService> _logger;
    private readonly string _dataPath;
    private readonly string _modelPath;

    public ModelTrainerService(ILogger<ModelTrainerService> logger, IWebHostEnvironment env)
    {
        _logger = logger;
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "customers.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "ChurnModel.zip");
    }

    public TrainingResult Train()
    {
        var mlContext = new MLContext(seed: 42);

        IDataView data = mlContext.Data.LoadFromTextFile<ChurnInput>(
            _dataPath, hasHeader: true, separatorChar: ',');

        // Map "Yes"/"No" string to boolean Label column
        var mappingAction = mlContext.Transforms.CustomMapping<ChurnInput, ChurnLabelMapping>(
            (input, output) => { output.Label = input.Churned == "Yes"; },
            contractName: "ChurnedToLabel");

        var pipeline = mappingAction
            .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", "Region"))
            .Append(mlContext.Transforms.Concatenate("Features", "Age", "Income", "PurchaseHistory", "RegionEncoded"))
            .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
                labelColumnName: "Label", featureColumnName: "Features"));

        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");

        _logger.LogInformation("Model Evaluation Metrics:");
        _logger.LogInformation("  AUC: {AUC:F4}", metrics.AreaUnderRocCurve);
        _logger.LogInformation("  F1 Score: {F1:F4}", metrics.F1Score);
        _logger.LogInformation("  Accuracy: {Accuracy:F4}", metrics.Accuracy);

        mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {ModelPath}", _modelPath);

        return new TrainingResult
        {
            AUC = metrics.AreaUnderRocCurve,
            F1Score = metrics.F1Score,
            Accuracy = metrics.Accuracy
        };
    }

    public class TrainingResult
    {
        public double AUC { get; set; }
        public double F1Score { get; set; }
        public double Accuracy { get; set; }
    }

    // Output class for the custom mapping
    public class ChurnLabelMapping
    {
        public bool Label { get; set; }
    }
}

