using Microsoft.Extensions.ML;
using ChurnPredictor.Models;
using ChurnPredictor.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<ModelTrainerService>();

var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "ChurnModel.zip");
if (File.Exists(modelPath))
{
    builder.Services.AddPredictionEnginePool<ChurnInput, ChurnPrediction>()
        .FromFile(modelPath: modelPath, watchForChanges: true);
}
else
{
    builder.Services.AddPredictionEnginePool<ChurnInput, ChurnPrediction>();
}

var app = builder.Build();

app.MapGet("/", () => "Hello");

app.MapPost("/train", (ModelTrainerService trainer) =>
{
    var result = trainer.Train();
    return Results.Ok(new
    {
        message = "Model trained successfully",
        metrics = new
        {
            result.AUC,
            result.F1Score,
            result.Accuracy
        }
    });
});

app.MapPost("/predict", (PredictRequest request, PredictionEnginePool<ChurnInput, ChurnPrediction> pool) =>
{
    var input = new ChurnInput
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region,
        PurchaseHistory = request.PurchaseHistory,
        Churned = string.Empty
    };

    var prediction = pool.Predict(input);

    return Results.Ok(new
    {
        willChurn = prediction.PredictedLabel ? "Yes" : "No",
        probability = prediction.Probability,
        score = prediction.Score
    });
});

app.Run();

